"""
	Detects whether a ``bytes`` object represents an integer.
	:param serialised: A ``bytes`` instance which must be identified as being an
	integer or not.
	:return: ``True`` if the ``bytes`` likely represent an integer, or ``False``
	if they do not.
	"""
def is_serialised(serialised: Any) -> object {
    first_byte = True;
    for byte in serialised {
        if (
            not ((byte >= b'0'[0]) and (byte <= b'9'[0]))
            and not (first_byte and (byte == b'-'[0]))
        ) {
            return False;
        }
        first_byte = False;
    }
    return not first_byte;
}

"""
    :param number: O numero do fatorial
    :return: Quantidade de digitos do fatorial de number.
    """
def kamenetsky(number: Any) -> object {
    import math;
    if (number < 0) {
        return 0;
    } elif (number <= 1) {
        return 1;
    }
    digits = (
        (number * math.log10((number / math.e)))
        + (math.log10((2 * math.pi * number)) / 2)
    );
    return (math.floor(digits) + 1);
}

"""
    Math is fun (Thanks Adrien and Eric)
    """
def binomial_coeff(n: Any, k: Any) -> object {
    import functools as ft;
    import operator as op;
    k = min(k, (n - k));
    n = ft.reduce(op.mul, range(n, (n - k), -1), 1);
    d = ft.reduce(op.mul, range(1, (k + 1)), 1);
    return (n / d);
}
